package net.officefloor.hq.app.pool;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.stream.IntStream;
import net.officefloor.hq.app.history.SheetHistory;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The pools on a sheet. The caller's signed-in name comes in the {@code X-User} header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/pools")
public class PoolController {

    /** A member as the pool's row shows it: a person (personId) or another pool (memberPoolId, its name as the
     *  name), with the membership's from-date and to-date (null: none); cut is its cut of the pool's pot, null when
     *  the pool shows none or the membership's dates do not include the sheet's today. */
    public record MemberView(Long personId, Long memberPoolId, String name, String share, boolean retired,
            String cut, LocalDate from, LocalDate to) {

        public static MemberView of(PoolService.Member m, BigDecimal cut) {
            String shown = cut == null || !m.inForce() ? null : cut.toPlainString();
            if (m.pool() != null) {
                return new MemberView(null, m.pool().getId(), m.pool().getName(), m.share().toPlainString(), false,
                        shown, m.from(), m.to());
            }
            return new MemberView(m.person().getId(), null, m.person().getName(), m.share().toPlainString(),
                    m.person().isRetired(), shown, m.from(), m.to());
        }
    }

    /** A pool as the screen shows it: its members, their total share and whether that is exactly 100.00; crew when it
     *  is the pool a crew is, its members the crew's lead and members (none can be added to it here). */
    public record PoolView(long id, String name, List<MemberView> members, String totalShare, boolean balanced,
            boolean crew) {

        public static PoolView of(PoolService.PoolWithMembers p) {
            List<BigDecimal> cuts = p.cuts();
            return new PoolView(p.pool().getId(), p.pool().getName(),
                    IntStream.range(0, p.members().size())
                            .mapToObj(i -> MemberView.of(p.members().get(i), cuts == null ? null : cuts.get(i))).toList(),
                    p.totalShare().toPlainString(), p.balanced(), p.pool().isCrew());
        }
    }

    /** A pool as the form submits it. */
    public record PoolForm(@NotNull @Size(max = 200) String name) {
    }

    /** A member as the pool's row submits it: a person or another pool of the sheet, exactly one given, with the
     *  membership's optional from-date and to-date. */
    public record MemberForm(Long personId, Long memberPoolId, @NotNull BigDecimal share, LocalDate from,
            LocalDate to) {
    }

    private final PoolService pools;

    public PoolController(PoolService pools) {
        this.pools = pools;
    }

    @GetMapping
    public List<PoolView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = SheetHistory.AS_OF_HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        // A sheet shown as of a date reads its pools with that date standing in for its today.
        return pools.list(sheetId, asOf).stream().map(PoolView::of).toList();
    }

    @PostMapping
    public PoolView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PoolForm request) {
        return PoolView.of(new PoolService.PoolWithMembers(pools.add(sheetId, user, request.name()), List.of(), null));
    }

    @PostMapping("/{poolId}/members")
    public PoolView addMember(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long poolId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody MemberForm request) {
        return PoolView.of(pools.addMember(sheetId, user, poolId, request.personId(), request.memberPoolId(),
                request.share(), request.from(), request.to()));
    }
}
package net.officefloor.hq.app.pool;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A pool on a sheet: a name its members share in, each with a share percent. */
@Entity
@Table(name = "pool")
public class Pool {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false, length = 200)
    private String name;

    protected Pool() {
    }

    public Pool(String sheetId, String name) {
        this.sheetId = sheetId;
        this.name = name;
    }

    /** The pool a crew is, under the crew's name: never stored, its id the crew's id negated so it is told apart from
     *  the stored pools. */
    public static Pool ofCrew(String sheetId, long crewId, String name) {
        Pool pool = new Pool(sheetId, name);
        pool.id = -crewId;
        return pool;
    }

    /** Whether this is the pool a crew is. */
    public boolean isCrew() {
        return id != null && id < 0;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }
}
package net.officefloor.hq.app.pool;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A membership of a pool, a person's or another pool's (exactly one is set), with its share percent of it. */
@Entity
@Table(name = "pool_member")
public class PoolMember {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "pool_id", nullable = false)
    private Long poolId;

    @Column(name = "person_id")
    private Long personId;

    @Column(name = "member_pool_id")
    private Long memberPoolId;

    @Column(name = "share", nullable = false, precision = 5, scale = 2)
    private BigDecimal share;

    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "to_date")
    private LocalDate to;

    protected PoolMember() {
    }

    public PoolMember(Long poolId, Long personId, BigDecimal share) {
        this.poolId = poolId;
        this.personId = personId;
        this.share = share;
    }

    /** A pool's membership of another pool. */
    public static PoolMember ofPool(Long poolId, Long memberPoolId, BigDecimal share) {
        PoolMember made = new PoolMember(poolId, null, share);
        made.memberPoolId = memberPoolId;
        return made;
    }

    public Long getId() {
        return id;
    }

    public Long getPoolId() {
        return poolId;
    }

    public Long getPersonId() {
        return personId;
    }

    /** The pool that is the member; null when the member is a person. */
    public Long getMemberPoolId() {
        return memberPoolId;
    }

    public BigDecimal getShare() {
        return share;
    }

    /** Make the membership another person's, keeping its place in the pool. */
    public void moveTo(Long personId) {
        this.personId = personId;
    }

    public void setShare(BigDecimal share) {
        this.share = share;
    }

    /** The first day the membership is in force; null: no start. */
    public LocalDate getFrom() {
        return from;
    }

    /** The last day the membership is in force; null: no end. */
    public LocalDate getTo() {
        return to;
    }

    /** Set the days the membership is in force, each end optional and inclusive. */
    public void setDates(LocalDate from, LocalDate to) {
        this.from = from;
        this.to = to;
    }

    /** Whether the membership's dates include {@code date}; with no date, only an undated membership does. */
    public boolean inForceOn(LocalDate date) {
        if (date == null) {
            return from == null && to == null;
        }
        return (from == null || !date.isBefore(from)) && (to == null || !date.isAfter(to));
    }
}
