        }).toList();
    }

    /** The claims as they stood then, unsaved, each with the id it had, in the order the sheet listed them. */
    public List<Claim> rebuildClaims(String sheetId) {
        return claims.stream().map(c -> {
            Claim claim = c.rebuild(sheetId);
